const source = ($json.body && typeof $json.body === 'object' && !Array.isArray($json.body)) ? $json.body : $json;
const fields = {
  name: typeof source.name === 'string' ? source.name.trim() : '',
  institution: typeof source.institution === 'string' ? source.institution.trim() : '',
  email: typeof source.email === 'string' ? source.email.trim() : '',
  subject: typeof source.subject === 'string' ? source.subject.trim() : '',
  message: typeof source.message === 'string' ? source.message.trim() : '',
  website: typeof source.website === 'string' ? source.website.trim() : ''
};

if (fields.website) {
  return [{
    json: {
      success: true,
      skipped: true,
      toEmail: 'vassili@gradesedu.eu',
      fromEmail: 'xenophon@grades-education.eu',
      replyToEmail: fields.email || 'vassili@gradesedu.eu',
      subjectLine: '[BTS Demo] Soumission ignoree (honeypot)',
      html: '<p>Soumission ignoree.</p>',
      ackToEmail: fields.email || 'vassili@gradesedu.eu',
      ackSubjectLine: 'Votre demande BTS a bien ete recue',
      ackHtml: '<p>Votre demande a bien ete recue.</p>'
    }
  }];
}

for (const key of ['name', 'institution', 'email', 'subject', 'message']) {
  if (!fields[key]) {
    throw new Error(`Champ requis manquant: ${key}`);
  }
}

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailPattern.test(fields.email)) {
  throw new Error('Adresse email invalide');
}

const escapeHtml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const submittedAt = new Date().toISOString();
const subjectLine = `[BTS Demo] ${fields.subject} - ${fields.name}`;
const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <style>
    body{margin:0;padding:32px;background:#12171e;color:#f2f3f5;font-family:Arial,sans-serif;line-height:1.6}
    .card{max-width:760px;margin:0 auto;padding:32px;border:1px solid rgba(143,210,255,.22);border-radius:24px;background:#171d26}
    h1{margin:0 0 24px;font-size:28px;color:#f7f2e8;font-family:Georgia,serif}
    dl{margin:0;display:grid;grid-template-columns:180px 1fr;gap:12px 18px}
    dt{font-weight:700;color:#8fd2ff}
    dd{margin:0}
    .message{margin-top:28px;padding-top:24px;border-top:1px solid rgba(242,243,245,.12)}
    p{margin:0;white-space:pre-wrap}
    .meta{margin-top:28px;font-size:14px;color:#b6c0c9}
  </style>
</head>
<body>
  <div class="card">
    <h1>Nouvelle demande de demo BTS</h1>
    <dl>
      <dt>Nom</dt><dd>${escapeHtml(fields.name)}</dd>
      <dt>Etablissement</dt><dd>${escapeHtml(fields.institution)}</dd>
      <dt>Email</dt><dd>${escapeHtml(fields.email)}</dd>
      <dt>Objet</dt><dd>${escapeHtml(fields.subject)}</dd>
    </dl>
    <div class="message">
      <p>${escapeHtml(fields.message)}</p>
    </div>
    <div class="meta">
      <p>Recu le ${escapeHtml(submittedAt)}</p>
    </div>
  </div>
</body>
</html>`;

const ackSubjectLine = 'Votre demande BTS a bien ete recue';
const ackHtml = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <style>
    body{margin:0;padding:32px;background:#12171e;color:#f2f3f5;font-family:Arial,sans-serif;line-height:1.6}
    .card{max-width:680px;margin:0 auto;padding:32px;border:1px solid rgba(143,210,255,.22);border-radius:24px;background:#171d26}
    h1{margin:0 0 20px;font-size:28px;color:#f7f2e8;font-family:Georgia,serif}
    p{margin:0 0 16px}
    .meta{margin-top:24px;font-size:14px;color:#b6c0c9}
  </style>
</head>
<body>
  <div class="card">
    <h1>Votre demande a bien ete recue</h1>
    <p>Bonjour ${escapeHtml(fields.name)},</p>
    <p>Nous avons bien recu votre demande de demonstration pour Grades Education BTS.</p>
    <p>Nous reviendrons vers vous rapidement a l'adresse <strong>${escapeHtml(fields.email)}</strong>.</p>
    <p class="meta">Message recu le ${escapeHtml(submittedAt)}.</p>
  </div>
</body>
</html>`;

return [{
  json: {
    ...fields,
    submittedAt,
    success: true,
    toEmail: 'vassili@gradesedu.eu',
    fromEmail: 'xenophon@grades-education.eu',
    replyToEmail: fields.email,
    subjectLine,
    html,
    ackToEmail: fields.email,
    ackSubjectLine,
    ackHtml
  }
}];
